package com.example.bikerental; import org.springframework.data.jpa.repository.JpaRepository; import java.util.List; public interface FavoriteRepository extends JpaRepository<Favorite,Long>{ List<Favorite> findByUsernameOrderByCreatedAtDesc(String username); List<Favorite> findByBikeId(Long bikeId); boolean existsByUsernameAndBikeId(String username,Long bikeId); void deleteByUsernameAndBikeId(String username,Long bikeId); }